#include "fixes/custom_map_asset_isolation/CurveLoadOrigin.h"
#include <cstdio>
namespace c=dluma::fixes::custom_map_asset_isolation::curves;
namespace f=dluma::fixes::custom_map_asset_isolation::file_lifetime;
#define CHECK(x) do {if(!(x)){std::printf("FAIL %d %s\n",__LINE__,#x);return false;}}while(0)
namespace {
c::CurveOpenedSource source(std::uint64_t root=11){return {{0x1000,{0x2000,3},4,root,f::FileKind::Zip,f::Life::Live},5,6,c::CurveSourceOwnership::ExclusiveProject};}
bool ExactOpenedSource(){c::CurveLoadToken t={};CHECK(c::BeginCurveLoadObservation("Data\\Curves\\fixture.xml",6,&t));auto o=source();c::NoteOpenedCurveSource("data/curves/fixture.xml",&o);c::CurveSourceReceipt r={};CHECK(c::CurrentCurveLoadSource(&r));CHECK(r.source.address==0x2000 && r.source.generation==3 && r.source_revision==5 && r.project_epoch==6);CHECK(c::EndCurveLoadObservation(&t));return true;}
bool SameFactoryReportsAreOneOpen(){c::CurveLoadToken t={};CHECK(c::BeginCurveLoadObservation("a.xml",6,&t));auto o=source();c::NoteOpenedCurveSource("a.xml",&o);o.file.file=0x3000;o.file.generation=9;c::NoteOpenedCurveSource("a.xml",&o);c::CurveSourceReceipt r={};CHECK(c::CurrentCurveLoadSource(&r));CHECK(c::EndCurveLoadObservation(&t));return true;}
bool DifferentOpenIsAmbiguous(){c::CurveLoadToken t={};CHECK(c::BeginCurveLoadObservation("a.xml",6,&t));auto a=source(),b=source(12);c::NoteOpenedCurveSource("a.xml",&a);c::NoteOpenedCurveSource("a.xml",&b);c::CurveSourceReceipt r={};CHECK(!c::CurrentCurveLoadSource(&r));CHECK(c::EndCurveLoadObservation(&t));return true;}
bool ForeignPathAndUntrackedAreNotGuessed(){c::CurveSourceReceipt r={};CHECK(!c::CurrentCurveLoadSource(&r));c::CurveLoadToken t={};CHECK(c::BeginCurveLoadObservation("a.xml",6,&t));auto o=source();c::NoteOpenedCurveSource("other.xml",&o);CHECK(!c::CurrentCurveLoadSource(&r));CHECK(c::EndCurveLoadObservation(&t));return true;}
bool NestedLoadsDoNotStealOrigins(){c::CurveLoadToken a={},b={};CHECK(c::BeginCurveLoadObservation("a.xml",6,&a));auto x=source();c::NoteOpenedCurveSource("a.xml",&x);CHECK(c::BeginCurveLoadObservation("b.xml",6,&b));auto y=source(22);y.file.source.address=0x9000;c::NoteOpenedCurveSource("b.xml",&y);c::CurveSourceReceipt r={};CHECK(c::CurrentCurveLoadSource(&r) && r.source.address==0x9000);CHECK(c::EndCurveLoadObservation(&b));CHECK(c::CurrentCurveLoadSource(&r) && r.source.address==0x2000);CHECK(c::EndCurveLoadObservation(&a));return true;}
bool WrongEpochAndEndedFilesRefuse(){c::CurveLoadToken t={};CHECK(c::BeginCurveLoadObservation("a.xml",7,&t));auto o=source();c::NoteOpenedCurveSource("a.xml",&o);c::CurveSourceReceipt r={};CHECK(!c::CurrentCurveLoadSource(&r));CHECK(c::EndCurveLoadObservation(&t));CHECK(c::BeginCurveLoadObservation("a.xml",6,&t));o.file.life=f::Life::Ended;c::NoteOpenedCurveSource("a.xml",&o);CHECK(!c::CurrentCurveLoadSource(&r));CHECK(c::EndCurveLoadObservation(&t));return true;}
}
int main(){bool(*tests[])()={ExactOpenedSource,SameFactoryReportsAreOneOpen,DifferentOpenIsAmbiguous,ForeignPathAndUntrackedAreNotGuessed,NestedLoadsDoNotStealOrigins,WrongEpochAndEndedFilesRefuse};for(auto t:tests)if(!t())return 1;std::printf("Curve load origin: %zu scenarios passed\n",sizeof(tests)/sizeof(tests[0]));return 0;}
